def execute(arguments):
    """
    解析JSON字符串

    参数:
        arguments (dict): 包含以下字段
            - json_string (str): JSON字符串，必填
            - path (str): 要提取的字段路径，用点号分隔，如 "data.items.0.name"，可选

    返回:
        dict: 包含解析结果的字典
            - success (bool): 是否成功
            - data (any): 解析后的完整数据（未指定path时）
            - value (any): 提取的字段值（指定path时）
            - path (str): 提取的路径（指定path时）
            - error (str): 错误信息（失败时）
    """
    import json

    json_string = arguments.get("json_string", "")
    json_path = arguments.get("path", "")

    if not json_string:
        return {"success": False, "error": "请提供JSON字符串"}

    try:
        data = json.loads(json_string)

        if json_path:
            keys = json_path.split(".")
            current = data
            for key in keys:
                if isinstance(current, dict):
                    current = current.get(key)
                elif isinstance(current, list):
                    try:
                        index = int(key)
                        current = current[index]
                    except ValueError:
                        return {"success": False, "error": f"无效的数组索引: {key}"}
                else:
                    return {"success": False, "error": f"无法访问路径: {json_path}"}

                if current is None:
                    return {"success": False, "error": f"路径不存在: {json_path}"}

            return {
                "success": True,
                "value": current,
                "path": json_path
            }
        return {
            "success": True,
            "data": data
        }
    except json.JSONDecodeError as e:
        return {"success": False, "error": f"JSON解析失败: {str(e)}"}
    except Exception as e:
        return {"success": False, "error": f"处理失败: {str(e)}"}
